import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    dp = [0] * (n + 1)
    max_length = 0
    count = 0

    for i in range(1, n + 1):
        if s[i - 1] == ')':
            if i - 2 >= 0 and s[i - 2] == '(':
                dp[i] = dp[i - 2] + 2
            elif i - dp[i - 1] - 1 >= 0 and s[i - dp[i - 1] - 1] == '(':
                dp[i] = dp[i - 1] + 2 + dp[i - dp[i - 1] - 2]
            if dp[i] > max_length:
                max_length = dp[i]
                count = 1
            elif dp[i] == max_length:
                count += 1

    if max_length == 0:
        print("0 1")
    else:
        print(f"{max_length} {count}")

main()
